mapper.select:
		 SELECT 

		 from activity
 		 where 1=1  

			 and id = #{record.id} 


			and activity_name like concat('%',#{record.activityName},'%')


			and activity_start_time >= #{record.activityStartTime}


			and activity_end_time <= #{record.activityEndTime}

		and del_flag = 0


				limit #{commonQueryParam.start}, #{commonQueryParam.pageSize}

		 SELECT 
		 count(1) 
		 from activity
 		 where 1=1  

			 and id = #{id} 


			and activity_name like concat('%',#{activityName},'%')


			and activity_start_time >= #{activityStartTime}


			and activity_end_time <= #{activityEndTime}

		and del_flag = 0

		 SELECT 

		 from activity
 		 where 1=1  

			 and id = #{id} 


			 and activity_name = #{activityName} 


			 and activity_start_time = #{activityStartTime} 


			 and activity_end_time = #{activityEndTime} 


			 and create_time = #{createTime} 


			 and update_time = #{updateTime} 


			 and del_flag = #{delFlag}
